-- Paŝoj al plena posedo : réponses types (« corrigé type » montré aux correcteurs), lot 8 : leçons 29 et 30.
-- Questions sur le texte et analyses de langue (29.3, 30.3), figures de style et métaphores (29.4, 30.4),
-- phrases à corriger selon l'intention des auteurs (29.4, 30.4).
-- Rédigées d'après les textes et les réponses cochées « juste » par les correcteurs ; à relire par Emmanuelle.
-- Ne remplace pas une réponse type existante ; peut être rejoué sans risque.
SET NAMES utf8mb4;

UPDATE ekzerceroj SET respondo = 'Sur unu pesiltelero li metus la grandegajn dimensiojn de la universo (la stela radio, kiu flugas miljarojn, la nombroj, la spaco, la mondoj), sur la alian la mallongan homan vivon, kiu ĝermas kaj velkas kiel grajno. Li demandas, ĉu tamen la kelkaj mizeraj jaroj de homo ne superpezus.' WHERE id = 2160 AND ekzerco_id = 273 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Ekzemple: “la plej silentega radio flugkuras miljarojn” (komence, en la mezo kaj fine); “estis simple la milito … la pesto … la morto”; “la neniesa tero”; “ja tiun jaron estis la milito”; “fermentadis la flavan argilon per la varmega sango”; “batalas por la libero … volas forrabi la karbon kaj feron”; “kiel la praulo, kiel la lupo”; “la odoro parenca kaj konata”. Tiuj refrenoj donas ritmon kaj insistas pri la sama sorto de ambaŭ soldatoj kaj pri la absurdeco de la milito.' WHERE id = 2161 AND ekzerco_id = 273 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Metita antaŭ “ne”, “ĝustatempe” ŝajnas diri, ke estis ĝustatempe ne plilongigi la vivon. La intencita senco estas, ke li ne sukcesis enspiri ĝustatempe: oni skribu “ne plilongigis ĝustatempe” (aŭ: “ne ĝustatempe plilongigis”).' WHERE id = 2162 AND ekzerco_id = 273 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Malsimilaĵoj: lando, lingvo, aspekto (nigrahara kaj blonda), laboro (vinberoj; terpomoj kaj bovinoj), plezuroj (muziko; keglado), edzinoj (bruna Jeanne, blanka Johanna). Similaĵoj: ambaŭ estas simplaj kamparanoj, kiuj ne scias, por kio ili batalas; ili ricevas la saman ordonon, skribas al siaj edzinoj, havas la saman soldatan odoron, mortas same, kaj iliaj vidvinoj reedziniĝas kun iu Paul. Persona opinio pri la unua demando. La aŭtoro opinias la similaĵojn pli gravaj; li sentigas tion per la paralela strukturo de la du portretoj kaj per la ripetoj.' WHERE id = 2163 AND ekzerco_id = 273 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Ne: li militis nur tial, ke estis milito; li ne sciis, ĉu Francujo batalas por la libero aŭ por karbo kaj fero.' WHERE id = 2164 AND ekzerco_id = 273 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Pri la vetero en Provenco: ke la sama varma nokto estus bona por la vinberoj kaj por Jeanne, kiu ŝatas varmajn noktojn. Tio montras, ke la soldatoj restas simplaj homoj, kies koro restas hejme, ĉe la laboro kaj la familio, kaj kiuj ne vere komprenas, por kio ili batalas.' WHERE id = 2165 AND ekzerco_id = 273 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Kiel lupo li fleksiĝis kaj streĉis sin, pretiĝante salti sur sian kaptaĵon; sed ambaŭ restis kuŝantaj sen komenci, kaj fine li proponis al Peter sian pipon.' WHERE id = 2166 AND ekzerco_id = 273 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = '(a) La milito estas absurda kaj indiferenta al la individuoj: la morto de la du homoj ŝanĝas nenion, novaj soldatoj tuj venas fari la samon, kaj la neniesa tero estas konkerita per multaj aliaj mortoj. (b) La vivo daŭras malgraŭ ĉio: la vidvinoj ploras kaj poste prenas novan edzon, ĉar la vinberoj kaj la bovinoj postulas zorgon. La vivo estas pli forta ol la morto.' WHERE id = 2167 AND ekzerco_id = 273 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Al du feliĉaj amantoj ĉirkaŭbrakumantaj unu la alian, ekkaptitaj de la morto. La komparo estas ironia, ĉar fakte ili mortis strangolante unu la alian; tamen ĝi sugestas ankaŭ la fratecon, kiu povus esti ekzistinta inter ili.' WHERE id = 2168 AND ekzerco_id = 273 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Persona opinio. Ekzemple: la fino revenas al la bildo de la komenco (la pesilo, la stela radio) kaj al la pipo, nun nomata “Pipo de Paco”; ĝi lasas la leganton kun amara demando pri la valoro de la mallonga homa vivo kaj pri la absurdeco de la milito.' WHERE id = 2169 AND ekzerco_id = 273 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Ironio: “miljara paco” neniam ekzistis, do nomi ĝin “rimarkinda fenomeno” estas moka.' WHERE id = 2170 AND ekzerco_id = 274 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Antonomazio: “napoleono” (laŭ Napoleono) signifas grandan gvidanton, ĉi tie financan geniulon. (Ĝi estas samtempe iom kalemburo, ĉar napoleono estas ankaŭ ora monero.)' WHERE id = 2171 AND ekzerco_id = 274 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Similigo: “kiel nupta barko” (kun personigo en “eknaĝas”).' WHERE id = 2172 AND ekzerco_id = 274 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Metaforo: “la brutaron de ĉagrenoj” (la ĉagrenoj estas bildigitaj kiel brutaro, kiun oni trenas post si).' WHERE id = 2173 AND ekzerco_id = 274 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Kalemburo: “kiumotive” (pro kiu motivo) kaj “lokomotive” (per lokomotivo) sonas simile, sed havas tute malsaman signifon.' WHERE id = 2174 AND ekzerco_id = 274 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Estas notinde, ke, sekve de la multa pruvmaterialo, kiun nia samideano povis disponigi, la eldonejo akceptis Esperanton, kvankam ĝis nun ĝi estis kontraŭ nia lingvo.' WHERE id = 2176 AND ekzerco_id = 276 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'La patrinoj faras sian eblon forigi de sur la reloj la infanojn, kaj ankaŭ la kokojn kaj la aliajn dombestojn. (“Ceterajn dombestojn” kalkulas la infanojn inter la dombestoj.)' WHERE id = 2177 AND ekzerco_id = 276 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Prelegis nia aminda instruistino.' WHERE id = 2178 AND ekzerco_id = 276 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Hieraŭ frumatene la metiistoj rapide pakis sian ekipaĵon kaj ĝentile formarŝis. (aŭ: Morgaŭ … pakos … formarŝos.)' WHERE id = 2179 AND ekzerco_id = 276 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Post du jaroj la patro de Aleksandro estis mortigita, kaj sekve Aleksandro surtroniĝis.' WHERE id = 2180 AND ekzerco_id = 276 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'La helpkuracisto estis homo nejuna kun grasa ventro kaj kalva kapo.' WHERE id = 2181 AND ekzerco_id = 276 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Elektis vin Dio, ho granda virino, por naski la Majstron. (“Naskigi” signifus “igi iun naski”.)' WHERE id = 2182 AND ekzerco_id = 276 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Montoj, surkreskitaj de abioj kaj piceoj, kaj belegaj sunaj valoj estas la vidindaĵoj de tiu ĉi regiono.' WHERE id = 2183 AND ekzerco_id = 276 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Malgraŭ landlimaj baroj, la esperantistoj devas kaj povas aranĝi ligojn inter la popoloj.' WHERE id = 2184 AND ekzerco_id = 276 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'La opinioj pri la valoro de la kiso estas tre malsamaj.' WHERE id = 2185 AND ekzerco_id = 276 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Origine tiuj adverboj bildigis la forton aŭ la sovaĝecon de besto (“kun besta forto”, ion ekscesan kaj nekontroleblan); poste ili fariĝis simplaj intensigiloj, kiuj signifas “tre, ege” (kiel en la franca “vachement”).' WHERE id = 2197 AND ekzerco_id = 279 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Surprizon kaj miron, ofte iom ironian (≈ “Mirinde!”, “Jen ja!”).' WHERE id = 2198 AND ekzerco_id = 279 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Ekzemple: “vi rigardas min kiel kolĥozprezidanto, kiun oni alvokis diri sian raporton latine”; “vi okulumadas kiel ia oĉjo tentanta per sukero”; “vi gapas kiel Kristoforo Kolumbo kredanta malkovri Amerikon”; “vi grimacas kiel iu glutinta skatolon da alumetoj”; “vi kondutas kiel episkopo perdinta la adreson de Disinjoro”; “vi silentas kiel melono sur glacio”. Ili estas trafaj, ĉar ili ŝerce bildigas la embarason kaj la tro grandan seriozecon de la sciencisto.' WHERE id = 2199 AND ekzerco_id = 279 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Melono = kapo: “vi havos fendon en la kapo”, t.e. vi havos problemojn, vi bedaŭros (ŝerca minaco: se vi ne decidos klare).' WHERE id = 2200 AND ekzerco_id = 279 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Mia monujo estas malplena: mi ne havas eĉ moneron por telefoni al iu amikino.' WHERE id = 2201 AND ekzerco_id = 279 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Li kaŝis sian stultecon per granda, aŭtoritata parolado kaj gravmieno, sed lia stulteco estis tiel granda, ke ĝi tamen montriĝis.' WHERE id = 2202 AND ekzerco_id = 279 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = '“Kapo” (scienca kapo, ĉefkapo, aŭtoĉara kapo, kunkapo).' WHERE id = 2203 AND ekzerco_id = 279 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Unue, kiam ŝi vidas la loĝejon, ŝi entuziasmas: “animale altara loko”, “Brute bela!”, “Kapacite altara!”. Kiam ŝi ekloĝas tie, ŝi trovas ĝin malmoderna (“Ne sufiĉe abstraktaj”, “ĉi tiun rancan trogloditejon”) kaj tute aliordigas ĝin.' WHERE id = 2204 AND ekzerco_id = 279 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Ŝi demandas, kio okazas, kio estas la problemo (≈ “Kio okazis? Kio ne funkcias?”), ĉar Dezsö kondutas strange.' WHERE id = 2205 AND ekzerco_id = 279 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'skrupulo + pedanto (skrup-ped-ant-aĵoj: skrupulaj pedantaĵoj).' WHERE id = 2206 AND ekzerco_id = 279 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'En la varmega urbo, ardanta kiel forno, la duŝilo pendas pala kaj sola kiel la luno super ĝi: la poeto inversigas la kutiman bildon kaj prezentas la duŝon kiel malproksiman, sopiratan freŝigon.' WHERE id = 2207 AND ekzerco_id = 280 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'La luno estas nomata per serio da metaforoj: lampo de amo kun virga masko, nuda mamo el latuno (pro ĝia ronda formo kaj flaveca brilo), iritilo de l’eterno, ĉar ĝi vekas en la homo la sopiron al la senfino.' WHERE id = 2208 AND ekzerco_id = 280 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'La silento estas komparata kun sorĉa reto, kiu envolvas ĉion; ĝi estas “viola” kiel la vespera krepusko: la koloro de la lumo transiras al la silento.' WHERE id = 2209 AND ekzerco_id = 280 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'La luna lumo estas komparata kun arĝenta pudro, kiun la luno ŝutas sur la nigrajn harojn: en la lunlumo la haroj ŝajnas arĝentaj.' WHERE id = 2210 AND ekzerco_id = 280 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'La maro estas personigita kiel zorgema dommastrino, kiu senĉese faldas silkan tolaĵon: la ondoj, kiuj senfine ruliĝas kaj susuras, similas al silkaj faldoj.' WHERE id = 2211 AND ekzerco_id = 280 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Nu, ĉu vi ankoraŭ ne estas kontentigita, ho postulemulino?' WHERE id = 2212 AND ekzerco_id = 281 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Ĝojigu la koron de via amiko, sendante al li tiun ĉi poŝtkarton.' WHERE id = 2213 AND ekzerco_id = 281 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'La kurso por komencantoj estis fermita la 12-an de aprilo kaj montris kontentigan rezulton.' WHERE id = 2214 AND ekzerco_id = 281 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'En Ĝenevo la soveta delegacio proponis projekton de ĝenerala senarmigo.' WHERE id = 2215 AND ekzerco_id = 281 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Propono (necerta): “… por fari al ni vojon, transiri malfermiĝintajn fendojn, travindante nin inter la arboj …” (la fendoj ne estis malfermitaj de iu, sed malfermiĝis mem).' WHERE id = 2216 AND ekzerco_id = 281 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Same kiel ekster nia movado, diverspecaj diplomatoj … (“simile kiel” miksas “simile al” kaj “same kiel”).' WHERE id = 2217 AND ekzerco_id = 281 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'La kamparano haltis kaj laŭte alvokis sian edzinon.' WHERE id = 2218 AND ekzerco_id = 281 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'La kongresanoj migris tra la urbo (aŭ: tra la arbaro) kaj vizitis la reĝan kastelon.' WHERE id = 2219 AND ekzerco_id = 281 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Ĉu la Esperanta instruado devas fariĝi aparta por ĉiu sekso, aŭ ĉu oni devas preferi la kuninstruadon de lernantoj de ambaŭ seksoj? (“Ambaŭseksaj lernantoj” estus lernantoj, kiuj havas ambaŭ seksojn.)' WHERE id = 2220 AND ekzerco_id = 281 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'La tuta loĝantaro estis kunligita per sanga fido kaj amikeco. (“Bindi” estas fari bindaĵon de libro.)' WHERE id = 2221 AND ekzerco_id = 281 AND COALESCE(respondo, '') = '';

-- Vérification
SELECT ekzerco_id, COUNT(*) AS demandoj, SUM(COALESCE(respondo, '') <> '') AS kun_respondo FROM ekzerceroj
  WHERE ekzerco_id IN (273, 274, 276, 279, 280, 281) AND forigita = 0 GROUP BY ekzerco_id;
